WF.uiState=function(){let _cache=null;return{load:function(){if(_cache)return _cache;try{const raw=localStorage.getItem("wf_checklist_ui_state");_cache=raw?JSON.parse(raw):{}}catch(err){console.error("Unreadable or corrupted localStorage UI state, reset.",err),_cache={}}return _cache},save:function(state){_cache=state;try{localStorage.setItem("wf_checklist_ui_state",JSON.stringify(state))}catch(err){console.error("Failed to save UI state to localStorage.",err)}},STORAGE_KEY:"wf_checklist_ui_state"}}();